
// ================= p1i: v12 icon registry — painted multi-colour SVG icons (one sprite of <symbol>s, shared gradients) =================
// Единый источник иконок интерфейса: ICONS[id] = [основа, детали]. Основа получает тёмный контур и золотистый ободок (halo),
// детали (блики, прожилки) рисуются поверх без контура. Сетка 32×32, контур 1,5, ободок +1 по краю силуэта.
// ico(id) → <svg class="ico ic"><use href="#i-id"/></svg>; спрайт вставляется в документ один раз. Старые одноцветные глифы IC
// остаются запасным вариантом (плейсхолдеры плиток предметов в data:URL, неизвестные id).
const ICO_OUT='#1d0f07', ICO_RIM='#f7d68e';
const _P=(v)=>+v.toFixed(2);
function icoPoly(cx,cy,r,n,rot=-90){ let d=''; for(let i=0;i<n;i++){ const a=(rot+i*360/n)*Math.PI/180; d+=(i?'L':'M')+_P(cx+Math.cos(a)*r)+' '+_P(cy+Math.sin(a)*r); } return d+'Z'; }
function icoStar(cx,cy,ro,ri,n,rot=-90){ let d=''; for(let i=0;i<n*2;i++){ const a=(rot+i*180/n)*Math.PI/180, r=i%2?ri:ro; d+=(i?'L':'M')+_P(cx+Math.cos(a)*r)+' '+_P(cy+Math.sin(a)*r); } return d+'Z'; }
function icoCog(cx,cy,ro,ri,n){ let d=''; const s=2*Math.PI/n; for(let i=0;i<n;i++){ const a=i*s-Math.PI/2; for(const [f,r] of [[0,ri],[.16,ro],[.44,ro],[.6,ri]]){ const b=a+f*s; d+=(d?'L':'M')+_P(cx+Math.cos(b)*r)+' '+_P(cy+Math.sin(b)*r); } } return d+'Z'; }
function icoHeart(cx,cy,s){ const p=(x,y)=>_P(cx+x*s)+' '+_P(cy+y*s); return `M${p(0,.95)}C${p(-1.55,-.05)} ${p(-1.2,-1.15)} ${p(0,-.5)}C${p(1.2,-1.15)} ${p(1.55,-.05)} ${p(0,.95)}Z`; }
// контурная линия: тёмная подложка + цветная линия
const icoL=(d,c,w=2)=>`<path d="${d}" fill="none" stroke="${ICO_OUT}" stroke-width="${w+1.6}"/><path d="${d}" fill="none" stroke="${c}" stroke-width="${w}"/>`;
const icoH=(d,o=.7,w=1.1,c='#fff')=>`<path d="${d}" fill="none" stroke="${c}" stroke-opacity="${o}" stroke-width="${w}" stroke-linecap="round"/>`;
const icoG=(id,a,b,c)=>`<linearGradient id="${id}" x1=".15" y1="0" x2=".85" y2="1"><stop offset="0" stop-color="${a}"/><stop offset=".5" stop-color="${b}"/><stop offset="1" stop-color="${c}"/></linearGradient>`;
const icoRG=(id,a,b,c,d,cy=.4)=>`<radialGradient id="${id}" cx=".4" cy="${cy}" r=".75"><stop offset="0" stop-color="${a}"/><stop offset=".3" stop-color="${b}"/><stop offset=".72" stop-color="${c}"/><stop offset="1" stop-color="${d}"/></radialGradient>`;
// цветовая семантика (README → «Иконки»): золото — валюта/награды, красный — здоровье/ярость/лавка, синий — магия/мана,
// зелёный — природа/питомцы/улучшение, фиолетовый — самоцветы/Бездна/руны, сталь — оружие/броня, дерево — стройка/ресурсы.
