// синонимы: id из данных игры → иконка
const ICO_ALIAS={sound:'roar',calendar:'cal',paw:'pets',know:'lore',jewel:'ring',all:'bag',quests:'quest',skin:'cloak',skins:'cloak',spin:'wheel',raid:'tower',net:'vece',chests:'chest',packs:'gifts',boosts:'boost',deals:'deal',settings:'gear',ok:'check'};
// одноцветная «кираса» для плейсхолдеров плиток (IC.chest занят сундуком)
IC.cuirass='<path d="M8 3l4 2 4-2 5 3-2 5-2-1v11H7V10l-2 1-2-5 5-3z"/>';
IC.flag='<path d="M5 2h2v20H5zM8 3h12l-3 5 3 5H8z"/>';
function icoId(n){ return ICONS[n]?n:ICO_ALIAS[n]&&ICONS[ICO_ALIAS[n]]?ICO_ALIAS[n]:null; }
function icoSpriteHTML(){ let s=''; for(const k in ICONS){ const [b,d]=ICONS[k];
    const halo=b.replace(/\s(?:fill|stroke|fill-opacity|stroke-opacity|opacity|stroke-dasharray)="[^"]*"/g,'').replace(/stroke-width="([\d.]+)"/g,(m,v)=>`stroke-width="${_P(+v+1.9)}"`);
    s+=`<symbol id="i-${k}" viewBox="0 0 32 32"><g fill="none" stroke="${ICO_RIM}" stroke-opacity=".55" stroke-width="3.4" stroke-linejoin="round" stroke-linecap="round">${halo}</g><g stroke="${ICO_OUT}" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round">${b}</g>${d||''}</symbol>`; }
  return `<svg id="icoSprite" xmlns="http://www.w3.org/2000/svg" width="0" height="0" aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden;pointer-events:none"><defs>${ICO_DEFS}</defs>${s}</svg>`; }
function icoInstall(){ if(document.getElementById('icoSprite')) return; const w=document.createElement('div'); w.innerHTML=icoSpriteHTML(); document.body.insertBefore(w.firstChild,document.body.firstChild); }
try{ icoInstall(); }catch(e){ console.warn('icoInstall',e); }
// бейдж «можно забрать»: число, если поводов больше одного (кольцо пульсирует — CSS .dot::after)
const dotHtml=(n,cls='')=>`<i class="dot${cls?' '+cls:''}${n>1?' n':''}">${n>1?(n>9?'9+':n):''}</i>`;
// разметка иконки: <use> на символ спрайта (дёшево: одна копия геометрии, градиенты общие)
function icoSvg(n,cls){ const id=icoId(n); if(id) return `<svg class="ico ic ic-${id} ${cls}" viewBox="0 0 32 32" aria-hidden="true"><use href="#i-${id}"/></svg>`;
  return `<svg class="ico ${cls}" viewBox="0 0 24 24" aria-hidden="true">${IC[n]||IC.spark}</svg>`; }
